INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('097cbb15-07ef-495c-adaa-d694cba6ad18', 'Data Scientist', 'situational', 'mid', 'A business team disagrees with your analysis conclusions. How do you handle the pushback?');
