INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('ef9b1310-2bdc-4857-8282-465a43788f9b', 'Data Scientist', 'situational', 'mid', 'You discover your training data contains a bias that could harm certain user groups. What''s your next step?');
