INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('c9393029-efab-409a-9e8d-c19d50f6c220', 'Data Scientist', 'situational', 'mid', 'Two competing hypotheses both seem plausible from your analysis. How do you decide which to pursue?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('9f8ffb6a-8e2e-431b-9319-c28e34df6660', 'Data Scientist', 'situational', 'mid', 'You have limited data to train a model that the business insists must be highly accurate. How do you manage expectations?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('e13ec990-3fb9-4cd0-9cfc-6841186bfc77', 'Data Scientist', 'situational', 'mid', 'A colleague''s analysis reaches a conclusion you believe is statistically flawed. How do you address it?');
