INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('d0aea546-0452-4803-be36-2fa5ab8b8002', 'Data Scientist', 'situational', 'mid', 'You find a data pipeline bug that has been silently corrupting reports for months. What do you do?');
