INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('891eaede-09e0-4184-a4df-2014e7da3cd7', 'Data Scientist', 'situational', 'mid', 'You''re asked to analyze a dataset outside your usual domain expertise. How do you get up to speed quickly?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('1ee26b93-d0b4-487a-9844-f1af18da0d9f', 'Data Scientist', 'situational', 'mid', 'Your analysis reveals a sensitive or controversial finding about the business. How do you present it?');
