INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('4cf392a4-f91c-450b-b1ab-257a2656e342', 'Data Scientist', 'situational', 'mid', 'You need to collaborate with engineers who have very different priorities than your data science team. How do you align?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('71bbeebb-b9de-4c95-a52b-78cb73488d8e', 'Data Scientist', 'situational', 'mid', 'You have conflicting definitions of a key metric across teams. How do you resolve it?');
