INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('850cd2b8-c43c-4db5-838b-3099764bacbf', 'Data Scientist', 'situational', 'mid', 'A dashboard you built is being misread by stakeholders to draw wrong conclusions. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('7f05b3ad-d4ab-4d45-8157-4b7e2655eba5', 'Data Scientist', 'situational', 'mid', 'You''re asked to reproduce a colleague''s results but can''t replicate them. How do you proceed?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('b9e8bef5-9cc2-45dc-8291-496346c0a09a', 'Data Scientist', 'situational', 'mid', 'You need to choose between a simple interpretable model and a complex, more accurate one. How do you decide?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('ae048b23-43b1-41d1-bbc3-cf3894c84c49', 'Data Scientist', 'situational', 'mid', 'Your recommendation based on data analysis conflicts with a senior leader''s gut instinct. How do you handle it?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('3bf7651a-0728-4922-a752-c6cffaad521c', 'Data Scientist', 'situational', 'mid', 'A/B test results show statistical significance but the effect size is tiny. How do you advise the business?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('8e7034f4-86c8-4fd2-8450-e7af60738bc8', 'Data Scientist', 'situational', 'mid', 'You''re asked to build a model quickly with data you haven''t had time to validate. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('9969a27f-8032-4ac7-a7c4-f92352ef8b5d', 'Data Scientist', 'situational', 'mid', 'Your team lacks the compute resources needed for a project. How do you adapt your approach?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('315a549a-cd2b-41ae-85ed-6efb526785c0', 'Data Scientist', 'situational', 'mid', 'You realize partway through a project that the original business question was poorly defined. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('f8199797-873f-4ec4-8fe2-c84f309c9ada', 'Product Manager', 'behavioral', 'mid', 'Tell me about a time you disagreed with a manager or teammate. How did you handle it?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('454e4779-0595-48a5-9375-141b3d797d93', 'Product Manager', 'behavioral', 'mid', 'Describe a situation where you had to meet a tight deadline. What did you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('d12bf9e7-6c9e-472e-bf6d-018163e90e10', 'Product Manager', 'behavioral', 'mid', 'Give an example of a time you made a mistake at work. How did you address it?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('1d05a5d7-e008-4557-a90b-6279d6dd9954', 'Product Manager', 'behavioral', 'mid', 'Tell me about a time you had to learn something new quickly to complete a task.');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('79c62f9e-eccd-4dbe-bf44-6acbf0935860', 'Product Manager', 'behavioral', 'mid', 'Describe a time you received difficult feedback. How did you respond?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('0579e583-ffe4-4749-9f14-d365070ade1b', 'Product Manager', 'behavioral', 'mid', 'Tell me about a project you''re most proud of and why.');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('4574cfb6-2abf-459f-9c78-a86d27582df1', 'Product Manager', 'behavioral', 'mid', 'Describe a time you had to persuade someone to see things your way.');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('7fab9b55-98c2-4404-8fce-9614d92eefb5', 'Product Manager', 'behavioral', 'mid', 'Tell me about a time you failed at something important. What did you learn?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('73764d9e-0d3b-4439-9566-6a8a7cf0abc2', 'Product Manager', 'behavioral', 'mid', 'Give an example of when you took initiative without being asked.');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('6939ed17-acd8-49db-87bd-e500e44a34de', 'Product Manager', 'behavioral', 'mid', 'Describe a time you had to work with someone whose working style was very different from yours.');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('8a3ead58-ba1a-413f-a07d-a443e0e456d2', 'Product Manager', 'behavioral', 'mid', 'Tell me about a time you had to prioritize multiple competing tasks.');
