INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('6324676f-ee4b-45ff-aaac-50d5f988bc9b', 'Sales Representative', 'situational', 'mid', 'You realize you overpromised on a feature during a sales pitch. What''s your next step?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('3e65cdfc-c965-472d-ac8f-7e783599fab2', 'Sales Representative', 'situational', 'mid', 'A key stakeholder in a deal leaves the company mid-negotiation. How do you adapt?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('09ca91e8-ebc9-4fa4-99a2-dc053cd58581', 'Sales Representative', 'situational', 'mid', 'Your product has a known issue that a prospect asks about directly. How do you handle it honestly?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('f0851e1d-ca6a-4666-a111-2df3267f6197', 'Sales Representative', 'situational', 'mid', 'A prospect wants a custom contract term outside your standard terms. How do you proceed?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('eb5b26d7-29ee-4488-8ef6-6eead04c89cd', 'Sales Representative', 'situational', 'mid', 'You''ve built strong rapport with a champion, but their boss is the real decision-maker and is unresponsive. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('4bca078c-4518-4b54-a6bd-df20349f63e7', 'Sales Representative', 'situational', 'mid', 'Your company changes pricing mid-negotiation with a prospect. How do you communicate it?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('43bd5afa-ca73-4adb-aa0a-a7490cabeb1b', 'Sales Representative', 'situational', 'mid', 'A customer wants a refund after using the product for months. How do you handle the request?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('305b1c89-cb85-4ef5-8422-c2b09a6bdd99', 'Sales Representative', 'situational', 'mid', 'You''re asked to take over a struggling account from another rep. Where do you start?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('580cd0f2-0941-46b3-a0ac-3902bcbee546', 'Sales Representative', 'situational', 'mid', 'A prospect''s procurement process suddenly stalls with no explanation. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('a8b7995d-70db-40e9-8853-57bbbc4b25e1', 'Sales Representative', 'situational', 'mid', 'You discover a competitor is offering a much lower price to your prospect. How do you respond?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('567092ee-0dae-4754-92ee-967fe462e52f', 'Sales Representative', 'situational', 'mid', 'Your top customer requests a meeting with your CEO to discuss dissatisfaction. How do you prepare?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('90ee9ddd-5afd-42c3-877f-fa065f6bd282', 'Sales Representative', 'situational', 'mid', 'A deal you were confident about gets lost to a competitor. How do you follow up?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('c2496787-c63d-4f2b-a2bb-e07d46d22584', 'Sales Representative', 'situational', 'mid', 'You have two high-priority deals closing on the same day and limited bandwidth. How do you manage both?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('c6be3ac1-87c4-4a0d-81a0-08c3df804bf6', 'Sales Representative', 'situational', 'mid', 'A prospect asks a technical question you can''t answer confidently. What do you do?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('d797ece9-48a0-436d-b562-5ca22cc735e9', 'Sales Representative', 'situational', 'mid', 'Your CRM shows conflicting notes from a previous rep about a prospect. How do you proceed?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('6ce1753b-fe93-4d5e-a72d-eefa23753fc8', 'Sales Representative', 'situational', 'mid', 'A customer is upset about a billing error unrelated to you. How do you handle their frustration?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('1e57d442-333d-4059-9487-fab134660745', 'Sales Representative', 'situational', 'mid', 'You''re asked to sell a new product you have limited training on. How do you prepare?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('6ad0cd57-0c95-40fb-adc8-51323b436295', 'Sales Representative', 'situational', 'mid', 'A prospect wants to loop in their legal team, which historically slows deals significantly. How do you manage the timeline?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('dd7761a8-dccf-4fbf-a257-df8b25fc9ad0', 'Sales Representative', 'situational', 'mid', 'Your discount authority isn''t enough to close a deal a prospect wants. How do you proceed?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('2245ad3a-a45e-417b-b9ba-927898bacad8', 'Sales Representative', 'situational', 'mid', 'A referral brings you a lead who turns out to be a poor fit for your product. How do you handle it?');
INSERT INTO question_bank (id, job_role, category, difficulty, question_text) VALUES ('b8568c79-1548-4abd-a914-2ae6d404aefc', 'Sales Representative', 'situational', 'mid', 'You''re new to a territory with no existing pipeline. How do you build momentum in the first 90 days?');
