-- ============================================================================
-- CogniHire question_bank seed data
-- 750 questions across 5 profession types
-- ============================================================================

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS users (
	id TEXT PRIMARY KEY,
	username TEXT NOT NULL UNIQUE COLLATE NOCASE,
	email TEXT UNIQUE COLLATE NOCASE,
	password_hash TEXT NOT NULL,
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS interviews (
	id TEXT PRIMARY KEY,
	user_id TEXT NOT NULL,
	job_role TEXT NOT NULL,
	interview_type TEXT NOT NULL,
	experience_level TEXT NOT NULL DEFAULT 'mid',
	question_count INTEGER NOT NULL CHECK (question_count BETWEEN 1 AND 100),
	status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'completed', 'cancelled')),
	started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	completed_at TEXT,
	FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS questions (
	id TEXT PRIMARY KEY,
	interview_id TEXT NOT NULL,
	question_number INTEGER NOT NULL CHECK (question_number > 0),
	question_text TEXT NOT NULL,
	source TEXT NOT NULL DEFAULT 'ai',
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	UNIQUE (interview_id, question_number),
	FOREIGN KEY (interview_id) REFERENCES interviews(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS responses (
	id TEXT PRIMARY KEY,
	interview_id TEXT NOT NULL,
	question_id TEXT NOT NULL,
	answer_text TEXT NOT NULL DEFAULT '',
	answer_mode TEXT NOT NULL DEFAULT 'text' CHECK (answer_mode IN ('text', 'audio', 'video', 'audio_video')),
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	FOREIGN KEY (interview_id) REFERENCES interviews(id) ON DELETE CASCADE,
	FOREIGN KEY (question_id) REFERENCES questions(id) ON DELETE CASCADE,
	UNIQUE (interview_id, question_id)
);

CREATE TABLE IF NOT EXISTS media_uploads (
	id TEXT PRIMARY KEY,
	response_id TEXT NOT NULL,
	media_type TEXT NOT NULL CHECK (media_type IN ('audio', 'video')),
	file_path TEXT NOT NULL,
	mime_type TEXT,
	file_size INTEGER CHECK (file_size IS NULL OR file_size >= 0),
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	FOREIGN KEY (response_id) REFERENCES responses(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS evaluations (
	id TEXT PRIMARY KEY,
	response_id TEXT NOT NULL UNIQUE,
	score REAL NOT NULL CHECK (score BETWEEN 0 AND 10),
	strengths_json TEXT NOT NULL DEFAULT '[]',
	weaknesses_json TEXT NOT NULL DEFAULT '[]',
	feedback TEXT NOT NULL DEFAULT '',
	recommendation TEXT NOT NULL DEFAULT '',
	raw_json TEXT,
	created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
	FOREIGN KEY (response_id) REFERENCES responses(id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS question_bank (
	id TEXT PRIMARY KEY,
	job_role TEXT NOT NULL,
	category TEXT NOT NULL,
	difficulty TEXT NOT NULL,
	question_text TEXT NOT NULL
);

