COMMIT;

CREATE INDEX IF NOT EXISTS idx_interviews_user_started ON interviews(user_id, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_questions_interview ON questions(interview_id, question_number);
CREATE INDEX IF NOT EXISTS idx_media_response ON media_uploads(response_id);
CREATE INDEX IF NOT EXISTS idx_question_bank_role_category ON question_bank(job_role, category, difficulty);

CREATE VIEW IF NOT EXISTS v_question_bank_by_role AS
SELECT id, job_role, category, difficulty, question_text
FROM question_bank;

CREATE VIEW IF NOT EXISTS v_interview_summary AS
SELECT
	i.id AS interview_id, i.user_id, u.username, i.job_role, i.interview_type,
	i.experience_level, i.question_count, i.status, i.started_at, i.completed_at,
	COUNT(DISTINCT q.id) AS questions_created,
	COUNT(DISTINCT r.id) AS responses_submitted,
	ROUND(AVG(e.score), 2) AS average_score
FROM interviews i
JOIN users u ON u.id = i.user_id
LEFT JOIN questions q ON q.interview_id = i.id
LEFT JOIN responses r ON r.interview_id = i.id
LEFT JOIN evaluations e ON e.response_id = r.id
GROUP BY i.id;

CREATE VIEW IF NOT EXISTS v_interview_answers AS
SELECT
	i.id AS interview_id, i.job_role, i.interview_type, u.username,
	q.question_number, q.question_text, q.source AS question_source,
	r.id AS response_id, r.answer_text, r.answer_mode, r.created_at AS answered_at,
	e.score, e.strengths_json, e.weaknesses_json, e.feedback, e.recommendation
FROM interviews i
JOIN users u ON u.id = i.user_id
JOIN questions q ON q.interview_id = i.id
LEFT JOIN responses r ON r.question_id = q.id
LEFT JOIN evaluations e ON e.response_id = r.id;

CREATE VIEW IF NOT EXISTS v_pending_questions AS
SELECT i.id AS interview_id, i.user_id, i.job_role,
	q.id AS question_id, q.question_number, q.question_text
FROM interviews i
JOIN questions q ON q.interview_id = i.id
LEFT JOIN responses r ON r.question_id = q.id
WHERE i.status = 'in_progress' AND r.id IS NULL;

CREATE VIEW IF NOT EXISTS v_media_uploads AS
SELECT m.id AS media_id, m.media_type, m.file_path, m.mime_type, m.file_size,
	m.created_at, r.id AS response_id, r.interview_id, q.question_number,
	q.question_text, i.job_role, u.username
FROM media_uploads m
JOIN responses r ON r.id = m.response_id
JOIN questions q ON q.id = r.question_id
JOIN interviews i ON i.id = r.interview_id
JOIN users u ON u.id = i.user_id;